namespace ghidra.app.plugin.core.datamgr.actions;



using docking;
using docking.action;
using docking.widgets.tree;
using docking.widgets.tree;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr;
using ghidra.app.plugin.core.datamgr.tree;
using ghidra.program.model.data;
using ghidra.util;
using ghidra.util;

public class CreateTypeDefFromDialogAction : AbstractTypeDefAction {

	private static readonly string NAME = "Create Typedef From Dialog";

	public CreateTypeDefFromDialogAction(DataTypeManagerPlugin plugin) : base(NAME, plugin)
    {
		setPopupMenuData(new MenuData(new string[] { "New", "Typedef..." }, null, "Create"));
	}

	/* @Override */
	public void actionPerformed(ActionContext context) {

		CategoryNode categoryNode = getCategoryNode(context);
		Category category = categoryNode.getCategory();
		CreateTypeDefDialog dialog =
			new CreateTypeDefDialog(plugin, category, categoryNode.getTreePath());
		dialog.setHelpLocation(new HelpLocation(plugin.getName(), NAME));
		plugin.getTool().showDialog(dialog);

		if (dialog.isCancelled()) {
			return;
		}

		string name = dialog.getTypeDefName();
		DataType dataType = dialog.getDataType();
		DataTypeManager dataTypeManager = category.getDataTypeManager();

		DataTypeArchiveGTree gTree = (DataTypeArchiveGTree) context.getContextObject();
		CategoryPath categoryPath = category.getCategoryPath();
		DataType newTypeDef =
			createTypeDef(dataTypeManager, dataType, categoryPath, context, categoryNode, name);
		if (newTypeDef == null) {
			return;
		}

		dataTypeManager.flushEvents();

		GTreeNode parentNode = categoryNode;
		string newNodeName = newTypeDef.getName();
		Swing.runLater(() => gTree.setSeletedNodeByName(parentNode, newNodeName));
	}

	/* @Override */
	public bool isEnabledForContext(ActionContext context) {
		CategoryNode categoryNode = getCategoryNode(context);
		if (categoryNode is BuiltInArchiveNode) {
			return false;
		}
		return categoryNode != null && categoryNode.isModifiable();
	}

	/* @Override */
	public bool isAddToPopup(ActionContext context) {
		CategoryNode categoryNode = getCategoryNode(context);
		if (categoryNode == null || !categoryNode.isEnabled()) {
			return false;
		}
		if (categoryNode is BuiltInArchiveNode) {
			return false;
		}
		return true;
	}

	private CategoryNode getCategoryNode(ActionContext context) {
		if (!(context is DataTypesActionContext)) {
			return null;
		}

		object contextObject = context.getContextObject();
		GTree gtree = (GTree) contextObject;

		TreePath[] selectionPaths = gtree.getSelectionPaths();
		if (selectionPaths.length != 1) {
			return null;
		}

		GTreeNode node = (GTreeNode) selectionPaths[0].getLastPathComponent();
		return getCategoryForNode(node);
	}

	private CategoryNode getCategoryForNode(GTreeNode node) {
		while (!(node is CategoryNode) && node != null) {
			node = node.getParent();
		}
		return (CategoryNode) node;
	}
}
